// Build-time only: evaluates the pinned original weapon presentation (client/weapon-visuals.ts weaponModifiers, enchantWeapon
// and the muzzle flash, client/melee-trails.ts, client/character-animation.ts attackPose) and three r180's primitive
// geometry. The expected values are never generated by the C# port.
// Usage: node tools/export_weapon_fixtures.mjs <pinned source checkout with node_modules> <temporary output directory>
import fs from 'node:fs';import path from 'node:path';import {fileURLToPath,pathToFileURL} from 'node:url';import {stripTypeScriptTypes} from 'node:module';import {createHash} from 'node:crypto';
const root=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'..'),source=path.resolve(process.argv[2]),temp=path.resolve(process.argv[3]);
const inventory=JSON.parse(fs.readFileSync(path.join(root,'tools/conversion-inventory.json')));
fs.mkdirSync(temp,{recursive:true});fs.writeFileSync(path.join(temp,'package.json'),'{"type":"module"}');
// Same verified transpile as tools/export_models.mjs: every source blob must match the inventory receipt.
for(const f of inventory.files.filter(f=>f.path.startsWith('src/')&&f.path.endsWith('.ts'))){const input=path.join(source,f.path);if(!fs.existsSync(input))continue;const b=fs.readFileSync(input);if(createHash('sha1').update(`blob ${b.length}\0`).update(b).digest('hex')!==f.gitBlob)throw Error('Source mismatch '+f.path);const out=path.join(temp,f.path.replace(/\.ts$/,'.js'));fs.mkdirSync(path.dirname(out),{recursive:true});let code=b.toString().replace(/import\s*\{([^}]+)\}\s*from\s*(['"])([^'"]+)\2/g,(whole,names,quote,module)=>{if(!module.startsWith('.'))return whole;let target=path.resolve(path.dirname(input),module.replace(/\.js$/,'.ts'));if(!fs.existsSync(target))return whole;let text=fs.readFileSync(target,'utf8'),kept=names.split(',').filter(n=>!new RegExp('(?:export\\s+)?(?:interface|type)\\s+'+n.trim().split(/\s+as\s+/)[0]+'\\b').test(text));return kept.length?'import {'+kept.join(',')+'} from '+quote+module+quote:'import '+quote+module+quote;});fs.writeFileSync(out,stripTypeScriptTypes(code,{mode:'transform'}));}
// One three instance for the probes and the transpiled source (ESM resolution through the source's node_modules).
if(!fs.existsSync(path.join(temp,'node_modules')))fs.symlinkSync(path.join(source,'node_modules'),path.join(temp,'node_modules'),'dir');
const T=await import(pathToFileURL(path.join(temp,'node_modules/three/build/three.module.js')));const load=p=>import(pathToFileURL(path.join(temp,'src',p+'.js')));
const {buildWeapon,weaponModifiers,enchantWeapon,BLADE_LENGTH}=await load('client/weapon-visuals'),{MeleeTrails}=await load('client/melee-trails'),{attackPose}=await load('client/character-animation');
const {statsFor,WEAPONS,CHIPS}=await load('shared/content'),{attackElements}=await load('shared/elements');
const r6=x=>Math.round(x*1e6)/1e6,arr=v=>v.toArray().map(r6);const ids=new Set(CHIPS.map(c=>c.id));
const check=chips=>{for(const id of Object.keys(chips))if(!ids.has(id))throw Error('Unknown chip '+id);return chips;};
const STATS=['extraProjectiles','homing','split','pierces','pong','boomerang','vacuum','impulse','shrapnel','staticEvery','reach','extraStrikes','burn','poison'];
const shape=g=>g.type==='BoxGeometry'?'cube':g.type==='SphereGeometry'?'sphere':g.type==='ConeGeometry'?'cone':g.type==='TorusGeometry'?'ring':g.type;
const piece=o=>({shape:shape(o.geometry),glow:o.material.type==='MeshBasicMaterial',shadow:o.castShadow,color:o.material.color.getHex(),p:arr(o.position),q:arr(o.quaternion),s:arr(o.scale)});
// three r180 primitives exactly as weapon-visuals.ts:9 builds them.
const geo=g=>({positions:[...g.getAttribute('position').array].map(r6),normals:[...g.getAttribute('normal').array].map(r6),indices:[...g.index.array]});
const geometry={cube:geo(new T.BoxGeometry(1,1,1)),sphere:geo(new T.SphereGeometry(1,8,6)),cone:geo(new T.ConeGeometry(1,1,5)),ring:geo(new T.TorusGeometry(1,.055,4,16))};
// Sockets per spec (blade tips and muzzles) and the shared blade lengths.
const sockets={};for(const spec of Object.keys(WEAPONS)){const w=new T.Group();buildWeapon(w,spec);sockets[spec]={tip:w.getObjectByName('blade-tip')?arr(w.getObjectByName('blade-tip').position):null,muzzle:w.getObjectByName('muzzle')?arr(w.getObjectByName('muzzle').position):null};}
// Chip modules (weaponModifiers) per case, after the per-frame animation at `time`.
const moduleCases=[
 ['pistol',{multishot:3,ricochet:3,velocity:4,homing:3,splitter:1,piercing:1,magazine:8,pong:1,boomerang:1,vacuum:1,'fire-rate':2,overclock:1,kinetic:1,demolition:2,shrapnel:1,static:1}],
 ['rifle',{broadside:2,ricochet:1,velocity:2,magazine:3,homing:1,'dense-core':1}],['machinegun',{buckshot:1,pong:1,overclock:4,fireworks:1}],
 ['fire',{multishot:2,torrent:1,ricochet:2,velocity:1,homing:1,splitter:2,piercing:1,pong:1,boomerang:1,vacuum:1,'cast-rate':1,meteor:1,tesla:1}],
 ['water',{multishot:1,needle:1}],['lightning',{multishot:3}],['darkness',{torrent:1,wrecking:1}],
 ['leet',{needle:2,ricochet:1,velocity:3,splitter:1,piercing:1,'cast-rate':2,fireworks:1}],
 ['sword',{reach:5,'echo-strike':2,'swing-rate':3,vacuum:1,juggernaut:1,demolition:1,static:2,shrapnel:1}],['daggers',{reach:1,ember:2,poison:1,'swing-rate':1}],
 ['greatsword',{hurricane:1,bloodblade:2,overclock:2}],['shield',{reach:2,kinetic:1,vacuum:1}],['emperor',{overclock:3,reach:2}],['ansatsuken',{overclock:1}],['sword',{}],
 ['pistol',{rubber:1,repulsor:1,bulldozer:1,pinball:1,banker:1}],['rifle',{rail:1,'sniper-focus':1,inferno:1}]];
const modules=[];for(const [spec,chips] of moduleCases)for(const time of [0,1.37]){check(chips);const w=new T.Group();buildWeapon(w,spec);weaponModifiers(w,{spec,chips,lastShot:-10},time);const s=statsFor(chips),g=w.getObjectByName('chip-modules');
 modules.push({spec,chips,time,stats:Object.fromEntries(STATS.map(k=>[k,r6(s[k])])),pieces:g?g.children.map(piece):[]});}
// Blade enchantments (enchantWeapon) on melee weapons: elements from the stats, as renderer.ts:129 passes them.
const enchantCases=[['sword',{ember:1}],['sword',{ember:6,poison:3}],['daggers',{poison:2}],['greatsword',{inferno:1}],['shield',{ember:2,plague:1}],['emperor',{ember:1}],['sword',{plague:1,poison:9}]];
const enchants=[];for(const [spec,chips] of enchantCases)for(const time of [0,.5,2.2]){check(chips);const w=new T.Group();buildWeapon(w,spec);const s=statsFor(chips),elements=attackElements(s.burn,s.poison);enchantWeapon(w,elements,time,chips);const g=w.getObjectByName('enchantment');
 enchants.push({spec,chips,time,burn:r6(s.burn),poison:r6(s.poison),pieces:g?g.children.map(piece):[]});}
// Muzzle flash frames (weaponModifiers' flash branch) in weapon space.
const flashes=[];for(const spec of ['pistol','rifle','machinegun'])for(const shot of [3.1,12.345,77.7])for(const age of [-.01,0,.02,.0374,.0376,.05,.0749,.0751,.2]){const w=new T.Group();buildWeapon(w,spec);weaponModifiers(w,{spec,chips:{},lastShot:shot},shot+age);const f=w.getObjectByName('muzzle-flash');f.updateMatrix();f.parent.updateMatrix();const m=f.matrix.clone().premultiply(f.parent.matrix),p=new T.Vector3(),q=new T.Quaternion(),sc=new T.Vector3();m.decompose(p,q,sc);
 flashes.push({spec,shot,time:shot+age,visible:f.visible,p:arr(p),q:arr(q),s:arr(sc)});}
// Sweep activation (MeleeTrails.sweeping over attackPose) for the source PlayerView fields.
const windows=[];for(const spec of ['sword','daggers','greatsword','shield','emperor','ansatsuken'])for(const rate of [1,1.5])for(const mode of ['swing','fallback','echo','roll']){
 const L=10,w=WEAPONS[spec],windup=w.windup/rate,p={hp:100,spec,chips:{},lastAttack:L,windup,attackRate:rate,attackIndex:1};
 if(mode==='swing'||mode==='roll'){p.swingAt=L+windup;p.swingUntil=p.swingAt+.16/rate;}if(mode==='echo'){p.swingAt=L+.08/rate;p.swingUntil=p.swingAt+.16/rate;}if(mode==='roll')p.roll={at:L+.1};
 const wu=p.swingAt!==undefined?Math.max(.025,p.swingAt-L):Math.max(.025,windup),wn=p.swingAt!==undefined?p.swingUntil-p.swingAt:.16/rate,rec=(spec==='greatsword'?.5:spec==='daggers'?.15:.3)/rate,edges=[wu*.88,wu+wn+.07,wu+wn+rec,.1];
 const samples=[];for(let k=-3;k<90;k++){const age=k*.0137;if(edges.some(e=>Math.abs(age-e)<.002))continue;samples.push([r6(age),MeleeTrails.sweeping(p,attackPose(p,L+age))?1:0]);}
 windows.push({spec,rate,mode,lastAttack:L,windup,swingAt:p.swingAt??null,swingUntil:p.swingUntil??null,rollAt:p.roll?.at??null,special:null,released:false,samples});}
for(const kind of ['sword-launch','wolf-spin','dagger-throw'])for(const released of [true,false]){const p={hp:100,spec:kind==='wolf-spin'?'greatsword':kind==='dagger-throw'?'daggers':'sword',chips:{},lastAttack:-10,windup:.1,attackRate:1,attackIndex:1,meleeAction:{kind,released,at:20}};windows.push({spec:p.spec,rate:1,mode:'special',lastAttack:-10,windup:.1,swingAt:null,swingUntil:null,rollAt:null,special:kind,released,samples:[[30.5,MeleeTrails.sweeping(p,attackPose(p,20.5))?1:0]]});}
// Swept ribbons: a synthetic blade (grip and blade-tip socket) driven through MeleeTrails.sample/update exactly as the
// renderer calls them. Inputs (grip, tip, on/off) are recorded per player and frame; outputs are recorded every few frames.
function sequence(name,spec,chips,quality,dt,frames,players,schedule,{gap=-1,back=-1,off=-1,reach=1,every=3}={}){
 const scene=new T.Scene(),trails=new MeleeTrails({sample(){}}),rigs=[];
 for(let i=0;i<players;i++){const group=new T.Group();group.position.set(i*1.7-1,0,.4*i);group.rotation.y=.7+i*.3;scene.add(group);const make=()=>{const w=new T.Group();group.add(w);const t=new T.Group();t.name='blade-tip';const s=sockets[spec].tip;t.position.set(s[0],s[1],s[2]);w.add(t);return w;};rigs.push({group,weapon:make(),offWeapon:make()});}
 const out={name,spec,chips,quality,inputs:[],frames:[]};let t=10;
 for(let k=0;k<frames;k++){t+=k===gap?.15:k===back?-.5:dt;const enabled=k!==off;const frame={time:t,enabled,players:[]};
  for(let i=0;i<players;i++){const r=rigs[i],[on,lastAttack,index]=schedule(k,i),hand=spec==='daggers'&&index%2===0?r.offWeapon:r.weapon;
   for(const w of [r.weapon,r.offWeapon]){w.position.set(.3*Math.sin(t*3+i),1.2+.1*Math.cos(t*5),.2*Math.sin(t));w.quaternion.setFromAxisAngle(new T.Vector3(.2,1,.3).normalize(),9*t+i).multiply(new T.Quaternion().setFromAxisAngle(new T.Vector3(1,0,0),.5*Math.sin(t*4)));w.scale.set(1,1,reach);}
   const p={id:'p'+i,hp:100,spec,chips,lastAttack,attackIndex:index},pose=on?{active:true,age:.5,windup:.5,window:1}:{active:false,age:0,windup:.5,window:1};
   r.group.updateMatrixWorld(true);const g=hand.getWorldPosition(new T.Vector3()),tip=hand.getObjectByName('blade-tip').getWorldPosition(new T.Vector3());
   frame.players.push({on:MeleeTrails.sweeping(p,pose),key:'p'+i+':'+lastAttack+':'+index,id:i,lastAttack,index,grip:arr(g),tip:arr(tip)});trails.sample(r,p,pose,t);}
  trails.update(dt,t,enabled,quality);out.inputs.push(frame);
  if(k%every===0||k===frames-1||k===back||k===off)out.frames.push({k,size:trails.size,sweeps:[...trails.sweeps.entries()].map(([key,s])=>{const pos=s.mesh.geometry.getAttribute('position'),col=s.mesh.geometry.getAttribute('color'),count=s.mesh.geometry.drawRange.count,n=count>0?count/6+1:0;
   return {key,color:s.mesh.material.color.getHex(),samples:s.samples.length,n,pos:[...pos.array.slice(0,n*6)].map(r6),glow:Array.from({length:n*2},(_,j)=>r6(col.getX(j)))};})});}
 return out;}
const strikes=(k,i)=>k<4?[false,9,1]:k<24?[true,9.5,1]:k<30?[false,9.5,1]:k<52?[true,10.5,2]:[false,10.5,2];
const sweeps=[
 sequence('sword 60 Hz full, reach 1.4, two strikes, time jumps back',"sword",{},1,1/60,70,1,strikes,{back:66,reach:1.4}),
 sequence('daggers 144 Hz reduced, main then off hand, ember',"daggers",{ember:1},.3,1/144,90,1,(k,i)=>k<10?[false,9,1]:k<40?[true,9.5,1]:k<50?[false,9.5,1]:k<80?[true,10.2,2]:[false,10.2,2],{every:4}),
 sequence('greatsword 30 Hz full, .15 s frame gap, poison then disabled',"greatsword",{poison:2},1,1/30,40,1,(k,i)=>k<3?[false,9,1]:k<30?[true,9.5,1]:[false,9.5,1],{gap:12,off:34}),
 sequence('sword 144 Hz full, the 48-sample cap truncates the ribbon',"sword",{poison:1},1,1/144,60,1,(k,i)=>k<4?[false,9,1]:k<44?[true,9.5,1]:[false,9.5,1],{every:5}),
 sequence('shield 60 Hz, 18 pilots sweep at once (16-sweep cap), echo colour',"shield",{'echo-strike':1},1,1/60,14,18,(k,i)=>k<2?[false,9,1]:[true,9.5+i*.01,1],{every:7})];
fs.writeFileSync(path.join(root,'Tests/weapon-presentation-parity.json'),JSON.stringify({commit:inventory.sourceCommit,three:'0.180.0',bladeLength:BLADE_LENGTH,sockets,geometry,modules,enchants,flashes,windows,sweeps})+'\n');
console.log('Exported',modules.length,'module,',enchants.length,'enchant,',flashes.length,'flash,',windows.length,'window cases and',sweeps.length,'sweep sequences');
